// Art v2: the Neon Strip's picture signs and facades (the owner's notes part 2, 2026-10-25: the panther, the tiger, "way
// more neon signs with cool designs", "at night it really comes alive, but still looks great during the day").
//   NP / NP_PAL       his two sign sheets as pixel neon on one palette: nine hues at four strengths (core, tube, fill,
//                     deep) over the sign's dark backing, or cut out. [w, rows]: '.' clear, '0' the backing
//   npPic(k)          a sign decoded: { w, h, px, pal, pe (each pixel's glow), glow } or null (neonsigns.js picOf)
//   dressFace(spec, N, ctx)     a front's dressing (N.dress): light strips, holo panels, AC units, a conduit and its
//                     cables - spec.cyber, painted under the signs by paintCyber; pushes their light
//   placePics(spec, keys, ctx)  the extra picture signs (N.pics) where the face has room, clear of the rest
//   backShutter(spec, ctx)      a back wall's roll shutter (before its signs)
// Pure and worker-safe.
import { F_GLASS } from './gbuf.js';

const CH = '.0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
// (each colour's glow: batch 2's toned-down neon - the tubes read through the bloom, the dark between them stays dark)
const NP_EMI = Array.from({ length: 39 }, (_, i) => (i === 0 ? 0 : i >= 37 ? 190 : [200, 170, 60, 0][(i - 1) % 4])), NP_EMI_P = NP_EMI.map((e, i) => (i && i <= 36 && (i - 1) % 4 === 2 ? 0 : e));
const cache = new Map();
export function npPic(k) {
  const D = NP[k];
  if (!D) return null;
  let P = cache.get(k);
  if (P) return P;
  const [w, s] = D, h = Math.round(s.length / w), px = new Int8Array(w * h);
  // (its glow: the mean of its tubes' colour)
  const g = [0, 0, 0];
  let n = 0;
  for (let i = 0; i < w * h; i++) {
    const v = CH.indexOf(s[i]) - 1;
    px[i] = v;
    if (v > 0 && (v - 1) % 4 === 1 && v <= 36) { const c = NP_PAL[v]; g[0] += c[0]; g[1] += c[1]; g[2] += c[2]; n++; }
  }
  // each pixel's glow: its colour's; a sign whose whole panel is lit in the sheet has its fill as paint; inside a broad
  // lit shape only its edge is a tube - so the strokes stand out and no sign glows as one block
  let f = 0;
  for (let i = 0; i < w * h; i++) if (px[i] > 0 && px[i] <= 36 && (px[i] - 1) % 4 === 2) f++;
  const E = f > w * h * 0.3 ? NP_EMI_P : NP_EMI, pe = new Uint8Array(w * h), at = (x, y) => (x < 0 || y < 0 || x >= w || y >= h ? 0 : E[px[y * w + x]] || 0);
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) { const e = at(x, y); pe[y * w + x] = e >= 170 && at(x - 1, y) >= 170 && at(x + 1, y) >= 170 && at(x, y - 1) >= 170 && at(x, y + 1) >= 170 ? 70 : e; }
  P = { w, h, px, pal: NP_PAL, panel: false, pe, glow: n ? g.map((q) => Math.round(q / n)) : [255, 80, 200] };
  cache.set(k, P);
  return P;
}

// ---- the facades ----------------------------------------------------------------------------------------------
const S = [0, 1, 0];
const NEONS = [[255, 60, 200], [70, 230, 255], [255, 80, 150], [170, 100, 255], [255, 190, 60], [110, 255, 150], [255, 110, 70]];
const hot = (c) => c.map((q) => Math.min(255, q * 0.62 + 92));
const L = (c) => c.map((q) => q / 255);
// a rect [x, v, w, h] clear of every one in `taken` (m: the margin between them)
const clear = (taken, x, v, w, h, m = 4) => taken.every(([a, b, c, d]) => x + w + m <= a || a + c + m <= x || v + h + m <= b || b + d + m <= v);
// the rects the signs already on the face take (neonsigns.js handNeon has laid them)
export function signRects(spec, picSize, bladeSize) {
  const out = [];
  for (const sg of spec.neonSigns || []) {
    if (sg.pic) { const [w, h] = picSize(sg.pic, sg.s || 2); out.push([sg.x, sg.v, w, h]); }
    else if (sg.blade) { const [w, h] = bladeSize(sg.blade); out.push([sg.x, sg.v, w, h]); }
    else out.push([sg.x, sg.v, sg.w, sg.h]);
  }
  return out;
}
// the extra picture signs: each where it first fits, scanning the face above the shopfront (top: the lowest it may sit),
// from the side away from the door - the signs stacked up a tall front, side by side on a wide one
export function placePics(spec, keys, ctx) {
  const { w, H, top, taken, picSize, lights, doorLeft } = ctx, out = spec.neonSigns;
  let n = 0;
  for (const k of keys) {
    const [pw, ph] = picSize(k, 2);
    if (pw > w - 12 || top + ph > H - 6) continue;
    let at = null;
    for (let v = top; v + ph <= H - 6 && !at; v += 6) {
      for (let i = 0; i <= w; i += 6) {
        const x = doorLeft ? w - pw - 6 - i : 6 + i;
        if (x < 6 || x + pw > w - 6) break;
        if (clear(taken, x, v, pw, ph)) { at = [x, v]; break; }
      }
    }
    if (!at) continue;
    const P = npPic(k), col = P ? P.glow : [255, 80, 200];
    out.push({ pic: k, x: at[0], v: at[1], s: 2, col });
    taken.push([at[0], at[1], pw, ph]);
    lights.push([at[0] + pw / 2, 40, Math.round(at[1] * 0.7), 240, L(col), 1.3, (ctx.rnd() < 0.3 ? 'neonf' : 'neon')]);
    n++;
  }
  return n;
}
// a back on an alley (N.dress.back): a roll shutter down over its ground floor, tagged - laid first, the signs round it
export function backShutter(spec, ctx) {
  const { w, rnd, taken } = ctx, sw = Math.min(w - 20, 56 + Math.floor(rnd() * 40)), sx = 8 + Math.floor(rnd() * Math.max(1, w - sw - 16));
  (spec.cyber ||= []).push({ k: 'shutter', x: sx, w: sw, h: 44, s: Math.floor(rnd() * 999), tag: NEONS[Math.floor(rnd() * 7)] });
  taken.push([sx, 0, sw, 46]);
}
// a Neon Strip front's (or back's) dressing: spec.cyber
export function dressFace(spec, N, ctx) {
  const { w, H, rnd, lights, taken } = ctx, D = N.dress === true ? {} : N.dress, cy = (spec.cyber ||= []);
  const col = NEONS[(N.col ?? 0) % 7], col2 = NEONS[((N.col ?? 0) + 3) % 7];
  const g0 = D.back ? 56 : 64;   // (the ground floor's height: neonsigns.js keeps to buildingH's)
  // light strips up the corners of a tall front
  if (!D.back && H >= 150 && rnd() < 0.7) {
    for (const x of [2, w - 4]) { cy.push({ k: 'strip', x, v0: g0 + 4, v1: H - 10, col: col2 }); taken.push([x - 2, g0, 6, H - g0]); }
    lights.push([w / 2, 12, Math.round(H * 0.6), 160, L(col2), 0.8, 'neon']);
  }
  // a conduit up the wall (behind the signs, as they're hung over it), its cables slung across to the far edge
  const px = rnd() < 0.5 ? 10 + Math.floor(rnd() * 20) : w - 14 - Math.floor(rnd() * 20);
  cy.push({ k: 'pipe', x: px, v0: 4, v1: H - 8 });
  for (let i = 0, nc = 1 + Math.floor(rnd() * 2); i < nc; i++) { const v = g0 + 14 + Math.floor(rnd() * Math.max(10, H - g0 - 40)); cy.push({ k: 'cable', x0: px + 2, v0: v, x1: px < w / 2 ? w - 2 : 2, v1: v - 6 + Math.floor(rnd() * 12), sag: 6 + Math.floor(rnd() * 8) }); }
  taken.push([px - 2, 4, 8, H - 12]);
  // holo panels on the upper floors: a screen of scanlines and a glyph, in the front's colours
  for (let t = 0, made = 0; t < 14 && made < (D.back ? 1 : 2) && H > g0 + 50; t++) {
    const pw = 22 + Math.floor(rnd() * 5) * 4, ph = 26 + Math.floor(rnd() * 4) * 6, x = 6 + Math.floor(rnd() * Math.max(1, w - pw - 12)), v = g0 + 10 + Math.floor(rnd() * Math.max(1, H - g0 - ph - 18));
    if (x + pw > w - 4 || v + ph > H - 8 || !clear(taken, x, v, pw, ph)) continue;
    const c = rnd() < 0.5 ? col : col2;
    cy.push({ k: 'holo', x, v, w: pw, h: ph, col: c, g: Math.floor(rnd() * 4), s: Math.floor(rnd() * 999) });
    taken.push([x, v, pw, ph]);
    lights.push([x + pw / 2, 30, v + ph / 2, 170, L(c), 1.0, rnd() < 0.4 ? 'neonf' : 'neon']);
    made++;
  }
  // AC units hung on the wall by the windows, dripping
  for (let t = 0, made = 0; t < 16 && made < 2 + Math.floor(w / 140); t++) {
    const x = 6 + Math.floor(rnd() * Math.max(1, w - 26)), v = g0 + 6 + Math.floor(rnd() * Math.max(1, H - g0 - 30));
    if (v + 12 > H - 8 || !clear(taken, x, v - 14, 16, 26, 2)) continue;
    cy.push({ k: 'ac', x, v }); taken.push([x, v - 14, 16, 26]); made++;
  }
}

// ---- painting -------------------------------------------------------------------------------------------------
// (G.ax, G.ay: the face's south-west corner on the ground; a face pixel at height v is at row G.ay - v)
const h3 = (a, b, s) => { let h = (a * 374761393 + b * 668265263 + s * 2147483647) | 0; h = (h ^ (h >>> 13)) * 1274126177; return ((h ^ (h >>> 16)) >>> 0) / 4294967296; };
export function paintCyber(G, spec) {
  for (const q of spec.cyber || []) PAINT[q.k](G, q);
}
const at = (G, X, Y, c, e, fl = 0) => { if (G.inside(X, Y) && G.alpha(X, Y)) G.put(X, Y, c, S, G.ay - Y, e, fl); };
const shade = (G, X, Y, k) => { if (!G.inside(X, Y) || !G.alpha(X, Y)) return; const j = (Y * G.w + X) * 4; for (let c = 0; c < 3; c++) G.col[j + c] = G.col[j + c] * k; };
const PAINT = {
  strip(G, q) {
    const X = G.ax + q.x, c = hot(q.col);
    for (let v = q.v0; v < q.v1; v++) { const Y = G.ay - v, seg = v % 9 === 0; at(G, X, Y, seg ? q.col : c, seg ? null : [q.col[0], q.col[1], q.col[2], 190]); at(G, X + 1, Y, q.col, [q.col[0], q.col[1], q.col[2], 120]); }
  },
  pipe(G, q) {
    const X = G.ax + q.x;
    for (let v = q.v0; v < q.v1; v++) {
      const Y = G.ay - v, br = v % 24 === 0;
      at(G, X, Y, br ? [70, 72, 80] : [52, 54, 62], null); at(G, X + 1, Y, br ? [90, 92, 100] : [74, 76, 86], null); at(G, X + 2, Y, [40, 40, 48], null);
      if (br) { at(G, X - 1, Y, [70, 72, 80], null); at(G, X + 3, Y, [70, 72, 80], null); }
    }
  },
  cable(G, q) {
    const n = Math.max(2, Math.abs(q.x1 - q.x0));
    for (let i = 0; i <= n; i++) { const t = i / n, X = Math.round(G.ax + q.x0 + (q.x1 - q.x0) * t), v = q.v0 + (q.v1 - q.v0) * t - q.sag * 4 * t * (1 - t); at(G, X, Math.round(G.ay - v), [24, 22, 28], null); }
  },
  holo(G, q) {
    const X0 = G.ax + q.x, Y0 = G.ay - q.v - q.h, c = q.col, dim = c.map((v) => Math.round(v * 0.22 + 10)), mid = c.map((v) => Math.round(v * 0.45 + 12));
    for (let y = 0; y < q.h; y++) for (let x = 0; x < q.w; x++) {
      const e = x === 0 || y === 0 || x === q.w - 1 || y === q.h - 1, corner = (x < 3 || x > q.w - 4) && (y < 3 || y > q.h - 4);
      if (e) at(G, X0 + x, Y0 + y, corner ? hot(c) : c, [c[0], c[1], c[2], corner ? 210 : 150], F_GLASS);
      else at(G, X0 + x, Y0 + y, y % 2 ? dim : mid, [c[0], c[1], c[2], y % 2 ? 18 : 46], F_GLASS);
    }
    // the glyph: lines of text, a ring, chevrons, a block character
    const gx = X0 + 4, gy = Y0 + 4, gw = q.w - 8, gh = q.h - 8, ink = (x, y) => at(G, gx + x, gy + y, hot(c), [c[0], c[1], c[2], 200], F_GLASS);
    if (q.g === 0) for (let r = 0; r < gh - 1; r += 4) { const len = Math.round(gw * (0.35 + 0.6 * h3(r, q.s, 1))); for (let x = 0; x < len; x++) if (h3(x, r, q.s) > 0.12) ink(x, r); }
    else if (q.g === 1) { const cx = gw / 2, cyy = gh / 2, R = Math.min(gw, gh) / 2 - 1; for (let y = 0; y < gh; y++) for (let x = 0; x < gw; x++) { const d = Math.hypot(x + 0.5 - cx, y + 0.5 - cyy); if (Math.abs(d - R) < 0.7 || Math.abs(d - R * 0.45) < 0.6) ink(x, y); } }
    else if (q.g === 2) for (let k = 0; k < 3; k++) for (let i = 0; i < gw / 2; i++) { const y = Math.round(k * gh / 3 + i * 0.6); if (y < gh) { ink(Math.round(gw / 2 - i), y); ink(Math.round(gw / 2 + i), y); } }
    else for (let y = 0; y < gh; y++) for (let x = 0; x < gw; x++) { const cx2 = Math.floor(x / 4), cy2 = Math.floor(y / 4); if ((x % 4 === 0 || y % 4 === 0) && h3(cx2, cy2, q.s) > 0.55) ink(x, y); }
  },
  ac(G, q) {
    const X0 = G.ax + q.x, Y0 = G.ay - q.v - 11;
    for (let y = 0; y < 11; y++) for (let x = 0; x < 15; x++) {
      const e = x === 0 || x === 14 || y === 10, top = y === 0, gr = y > 1 && y < 9 && x > 1 && x < 8 && y % 2 === 0, fan = Math.hypot(x - 10.5, y - 5) < 3.2;
      at(G, X0 + x, Y0 + y, top ? [196, 198, 202] : e ? [110, 112, 118] : gr || fan ? [92, 94, 100] : [158, 160, 166], null);
    }
    for (let x = 2; x < 14; x += 10) for (let y = 11; y < 14; y++) at(G, X0 + x, Y0 + y, [60, 62, 68], null);   // (its brackets)
    for (let y = 14; y < 26; y++) if (h3(q.x, y, 3) > 0.2) shade(G, X0 + 4 + (y % 3 === 0 ? 1 : 0), Y0 + y, 0.82);   // (the drip's stain)
  },
  shutter(G, q) {
    const X0 = G.ax + q.x;
    for (let v = 0; v < q.h; v++) for (let x = 0; x < q.w; x++) {
      const Y = G.ay - v, slat = v % 3, e = x === 0 || x === q.w - 1, bar = v < 2, box = v >= q.h - 5;
      at(G, X0 + x, Y, e || bar ? [58, 60, 70] : box ? [74, 76, 86] : slat === 0 ? [72, 76, 88] : slat === 1 ? [104, 108, 120] : [90, 94, 106], null);
    }
    // the tag: a fat sprayed word in two colours (blobs along a wobbling line) and its drips
    const t = q.tag, t2 = [t[2], t[0], t[1]], n = Math.floor(q.w * 0.7), x0 = Math.round(q.w * 0.15);
    for (let i = 0; i < n; i++) {
      const vy = 16 + Math.round(6 * Math.sin(i * 0.4 + q.s)) + Math.round(h3(i, q.s, 2) * 2), r = h3(i >> 2, q.s, 4) > 0.3 ? 4 : 2;
      for (let dy = -r; dy <= r; dy++) at(G, X0 + x0 + i, G.ay - vy - dy, Math.abs(dy) === r ? t2 : t, null);
      if (h3(i, q.s, 5) > 0.93) for (let d = 1; d < 6; d++) at(G, X0 + x0 + i, G.ay - vy + r + d, t, null);
    }
    for (let k = 0; k < 2; k++) { const x = X0 + Math.round(q.w * (0.3 + k * 0.4)); for (let dx = 0; dx < 3; dx++) at(G, x + dx, G.ay - 1, [200, 170, 60], null); }   // (the padlocks)
  },
};

